### Implement React Card Component with Children Prop

Source: https://github.com/reactjs/react.dev/blob/main/src/content/learn/passing-props-to-a-component.md

This complete React application demonstrates the use of the `children` prop. The `Card` component receives an `Avatar` component (or any other JSX) via its `children` prop, rendering it within a wrapper div. It includes `App.js` for component composition, `Avatar.js` as a reusable sub-component, `utils.js` for image URL generation, and CSS for visual presentation.

```js
import Avatar from './Avatar.js';

function Card({ children }) {
  return (
    <div className="card">
      {children}
    </div>
  );
}

export default function Profile() {
  return (
    <Card>
      <Avatar
        size={100}
        person={{
          name: 'Katsuko Saruhashi',
          imageId: 'YfeOqp2'
        }}
      />
    </Card>
  );
}
```

```js
import { getImageUrl } from './utils.js';

export default function Avatar({ person, size }) {
  return (
    <img
      className="avatar"
      src={getImageUrl(person)}
      alt={person.name}
      width={size}
      height={size}
    />
  );
}
```

```js
export function getImageUrl(person, size = 's') {
  return (
    'https://i.imgur.com/' +
    person.imageId +
    size +
    '.jpg'
  );
}
```

