### React Timer Component with Stale `increment` in `useEffect` (Problem)

Source: https://github.com/reactjs/react.dev/blob/main/src/content/learn/separating-events-from-effects.md

This React functional component implements a timer that updates a `count` state every second. It uses an `increment` state variable, controlled by buttons, to determine the update amount. The `useEffect` hook incorrectly specifies an empty dependency array `[]`, causing the `increment` value captured in the closure to be stale and not reflect changes from the UI buttons.

```js
import { useState, useEffect } from 'react';

export default function Timer() {
  const [count, setCount] = useState(0);
  const [increment, setIncrement] = useState(1);

  useEffect(() => {
    const id = setInterval(() => {
      setCount(c => c + increment);
    }, 1000);
    return () => {
      clearInterval(id);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <>
      <h1>
        Counter: {count}
        <button onClick={() => setCount(0)}>Reset</button>
      </h1>
      <hr />
      <p>
        Every second, increment by:
        <button disabled={increment === 0} onClick={() => {
          setIncrement(i => i - 1);
        }}>–</button>
        <b>{increment}</b>
        <button onClick={() => {
          setIncrement(i => i + 1);
        }}>+</button>
      </p>
    </>
  );
}
```

